{
  "round": 1,
  "streams": [
    {
      "id": "D01",
      "description": "Workplace email action-item detection and extraction: detect source-grounded passages that require action or response without turning mere mentions, suggestions, or dates into obligations."
    },
    {
      "id": "D02",
      "description": "Email speech-act classification for requests and commitments, especially distinctions between directive/request and commissive/commitment acts."
    },
    {
      "id": "D03",
      "description": "Structured request and commitment argument extraction: recover actors or owners, actions, objects or targets, recipients, deadlines, conditions, exceptions, and supporting source spans."
    },
    {
      "id": "D06",
      "description": "Workplace action/request corpora and annotation schemas that empirically distinguish action-bearing acts and difficult request/commitment phenomena."
    },
    {
      "id": "T01",
      "description": "Meeting action-item detection and argument annotation, including task, owner, timeframe, agreement, and source-grounded task description extraction."
    },
    {
      "id": "T02",
      "description": "Meeting decision detection: identify decision discussions, resolution-related dialogue roles, and source-grounded decision content."
    },
    {
      "id": "T03",
      "description": "Dialogue-act and illocutionary-force classification using conversational and sequential context."
    },
    {
      "id": "T07",
      "description": "Conditionality, negation, hedge, and modality scope over events or propositions, needed to avoid promoting negated, hypothetical, or qualified actions into live obligations."
    },
    {
      "id": "T08",
      "description": "Temporal expression recognition and event-time linking, including explicit representation of relations between events and temporal expressions."
    }
  ],
  "decisions": [
