      "confidence": 0.95
    },
    {
      "paper_id": "doi-10-18653-v1-2007-sigdial-1-4",
      "decision": "ADMIT",
      "reason": "T01. It goes beyond classifying action-item utterances: it detects the surrounding subdialogue where an item is proposed, discussed, and committed to, then semantically parses source phrases to summarize the task. That materially strengthens source-grounded action extraction and the distinction between discussion and commitment.",
      "stream_id": "T01",
      "role": "TRANSFER",
      "confidence": 0.99
    },
    {
      "paper_id": "doi-10-3115-1564535-1564540",
      "decision": "ADMIT",
